typedef struct {
  int tokens;
  int rate; // tokens/sec
  int bucket;
  spinlock_t lock;
} vm_throttle_t;

void on_io_arrival(vm_throttle_t* t) {
  acquire(&t->lock);
  if (t->tokens > 0) { t->tokens--; enqueue_io(); }
  else { defer_io(); }
  release(&t->lock);
